const teacherId = variables['e465bb5c-de43-4e63-94d1-45e100b3efc4']?.user_id;
const period = variables['51b9f7f6-dbc6-4931-9548-e48fb612712f'] || 'monthly';
const token = localStorage.getItem('authToken') || sessionStorage.getItem('authToken') || '';
const anonKey = 'eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6ImtvdHp4cWthZ3B0Y29rcGF2aW9sIiwicm9sZSI6ImFub24iLCJpYXQiOjE3NzY0NTAwNjMsImV4cCI6MjA5MjAyNjA2M30.hxMfM3Wll6Al9n55FORzCkGACCZijOpHmTE0VSrN_88';

if (!teacherId) { alert('Missing teacher. Please go back to the tutor profile and try again.'); return; }

const isTransfer = variables['07217121-00d1-450f-9ce7-2deffd507299'] === true;

if (isTransfer) {
  const info = variables['bbfed0b9-6c8e-4b12-bd6c-9a15ad09618a'];
  if (!info) { alert('Please select the teacher you are transferring from first.'); return; }
  const amountDue = Number(info.amount_due || 0);

  if (amountDue > 0) {
    // Extra payment needed: go through Stripe. The webhook finalizes the transfer
    // (cancels old subscription, creates the new one) only after payment succeeds.
    try {
      const res = await fetch('https://kotzxqkagptcokpaviol.supabase.co/functions/v1/create-checkout-session', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json', 'apikey': anonKey, 'Authorization': 'Bearer ' + anonKey },
        body: JSON.stringify({
          authToken: token,
          type: 'transfer',
          teacher_id: teacherId,
          old_subscription_id: info.old_subscription_id,
          new_lessons_per_week: info.lessons_per_week,
          new_period: info.billing_period,
          success_url: 'https://kotzxqkagptcokpaviol.supabase.co/functions/v1/payment-return?status=success',
          cancel_url: 'https://kotzxqkagptcokpaviol.supabase.co/functions/v1/payment-return?status=cancelled'
        })
      });
      const data = await res.json();
      if (!res.ok || !data.url) {
        alert(data?.error || 'Could not start checkout for the plan change.');
        return;
      }
      window.open(data.url, '_blank');
    } catch (e) {
      alert('Network error. Please try again.');
    }
    return;
  }

  // No extra payment needed: the transfer is fully covered by the old plan's
  // remaining value, so it can apply immediately without going through Stripe.
  try {
    const res2 = await fetch('https://kotzxqkagptcokpaviol.supabase.co/rest/v1/rpc/execute_subscription_transfer', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json', 'apikey': anonKey, 'Authorization': 'Bearer ' + anonKey },
      body: JSON.stringify({
        p_token: token,
        p_old_subscription_id: info.old_subscription_id,
        p_new_teacher_id: teacherId,
        p_new_lessons_per_week: info.lessons_per_week,
        p_new_period: info.billing_period
      })
    });
    if (!res2.ok) {
      const errText = await res2.text();
      alert('Could not complete the transfer: ' + errText);
      return;
    }
    alert('Your lessons have been transferred to your new teacher!');
  } catch (e) {
    alert('Network error while finalizing the transfer.');
  }
  return;
}

// Normal (non-transfer) subscription flow: opens Stripe checkout. The subscription
// row is created as 'pending_payment' and only flips to 'active' once the
// stripe-webhook confirms the payment succeeded — never before.
const lessonsPerWeek = variables['942cbc96-c607-4ae5-a056-b5c19ad12ad9'] || 1;
try {
  const res = await fetch('https://kotzxqkagptcokpaviol.supabase.co/functions/v1/create-checkout-session', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json', 'apikey': anonKey, 'Authorization': 'Bearer ' + anonKey },
    body: JSON.stringify({
      authToken: token,
      type: 'subscription',
      teacher_id: teacherId,
      lessons_per_week: lessonsPerWeek,
      period: period,
      success_url: 'https://kotzxqkagptcokpaviol.supabase.co/functions/v1/payment-return?status=success',
      cancel_url: 'https://kotzxqkagptcokpaviol.supabase.co/functions/v1/payment-return?status=cancelled'
    })
  });
  const data = await res.json();
  if (!res.ok || !data.url) {
    alert(data?.error || 'Could not start checkout. Please try again.');
    return;
  }
  window.open(data.url, '_blank');
} catch (e) {
  alert('Network error. Please try again.');
}

